/**
 * Simulated crew of the fictional Aster-1 mission, for the Crew Average Comparison.
 *
 * SIMULATED DEMO LOGIC: every value is invented for the demonstration and generated by
 * code written with AI assistance. It is not real astronaut data and not derived from any
 * dataset (docs/data-and-limitations.md). Kept apart from the astronaut's own entries:
 * nothing here is stored, and it is never passed to the rule evaluation.
 */
import { addDays } from '@/domain/dates'
import type { HealthEntry } from '@/domain/indicators'
import { DEMO_DAYS } from '@/demo/demo'

import type { CrewDataSource, CrewEntry } from './compare'

/** The selected astronaut (Alex Morgan, the demo profile). */
export const SELF_ID = 'aster1-alex'

/**
 * The other five fictional crew members. Members are identified only by an id; no names
 * are attached to measurements, and the UI shows counts only.
 */
const MEMBERS = [
  {
    id: 'aster1-b',
    bp: [112, 72],
    hr: 60,
    glucose: 86,
    temp: 36.6,
    sleep: 7.3,
    mood: 4,
    method: 'oral',
  },
  {
    id: 'aster1-c',
    bp: [118, 77],
    hr: 66,
    glucose: 91,
    temp: 36.7,
    sleep: 6.9,
    mood: 4,
    method: 'oral',
  },
  {
    id: 'aster1-d',
    bp: [108, 70],
    hr: 58,
    glucose: 84,
    temp: 36.5,
    sleep: 7.6,
    mood: 3,
    method: 'oral',
  },
  {
    id: 'aster1-e',
    bp: [121, 79],
    hr: 69,
    glucose: 94,
    temp: 36.8,
    sleep: 7.0,
    mood: 4,
    method: 'oral',
  },
  // Uses the forehead sensor, so it never joins the oral comparison (and alone, no forehead average is shown).
  {
    id: 'aster1-f',
    bp: [115, 74],
    hr: 63,
    glucose: 88,
    temp: 36.4,
    sleep: 7.2,
    mood: 5,
    method: 'forehead',
  },
] as const

function mulberry32(seed: number) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const round = (value: number, decimals = 0) => Math.round(value * 10 ** decimals) / 10 ** decimals

/**
 * Readings for the 14 days before `now` and today, one per indicator per member per day,
 * with the same seed every time. Shared trends over the last 5 days (all members): resting
 * heart rate rises by up to 4 bpm and sleep falls by up to 0.6 h, so a change seen in one
 * person can be set against the crew. Some days are skipped, and some readings lack the
 * context needed for a comparison, to show how gaps and exclusions are handled.
 */
export function createCrewEntries(now: Date): CrewEntry[] {
  const random = mulberry32(42)
  const jitter = (spread: number) => (random() * 2 - 1) * spread
  const entries: CrewEntry[] = []

  for (let offset = DEMO_DAYS; offset >= 0; offset--) {
    const day = addDays(now, -offset)
    day.setHours(7, 0, 0, 0)
    const midnight = new Date(day)
    midnight.setHours(0, 0, 0, 0)
    // 0 for older days, rising to 1 today.
    const trend = offset < 5 ? (5 - offset) / 5 : 0

    MEMBERS.forEach((m, index) => {
      // About one day in eight is skipped per member (never today, so today has a comparison).
      if (offset > 0 && random() < 0.12) return
      // 07:00 plus a few minutes per member; never after `now` and never before midnight.
      const at = new Date(
        Math.max(
          midnight.getTime(),
          Math.min(day.getTime() + index * 7 * 60_000, now.getTime() - (index + 1) * 60_000),
        ),
      ).toISOString()
      const base = (name: string) => ({
        id: `crew-${m.id}-${name}-${offset}`,
        recordedAt: at,
        origin: 'simulated' as const,
      })
      const push = (entry: HealthEntry) => entries.push({ memberId: m.id, entry })

      push({
        ...base('bp'),
        indicator: 'bloodPressure',
        systolicMmHg: round(m.bp[0] + jitter(5)),
        diastolicMmHg: round(m.bp[1] + jitter(4)),
      })
      // Mostly at rest; now and then after activity, and once in a while not recorded.
      const roll = random()
      push({
        ...base('hr'),
        indicator: 'heartRate',
        bpm: round(m.hr + 4 * trend + jitter(3) + (roll > 0.9 ? 25 : 0)),
        ...(roll > 0.9
          ? { activity: 'afterActivity' as const }
          : roll > 0.85
            ? {}
            : { activity: 'rest' as const }),
      })
      push({
        ...base('glucose'),
        indicator: 'bloodGlucose',
        mgDl: round(m.glucose + jitter(5)),
        context: random() < 0.08 ? 'unknown' : 'fasting',
        device: 'fingerstick',
      })
      push({
        ...base('temp'),
        indicator: 'bodyTemperature',
        celsius: round(m.temp + jitter(0.2), 1),
        method: m.method,
        exercisedLast30Min: random() < 0.05,
      })
      push({
        ...base('sleep'),
        indicator: 'sleep',
        hours: round(m.sleep - 0.6 * trend + jitter(0.5), 1),
        source: 'selfReport',
      })
      push({
        ...base('mood'),
        indicator: 'mood',
        kind: 'dailyRating',
        rating: Math.min(5, Math.max(1, round(m.mood + jitter(1)))),
      })
      // A PHQ-2 per member, which the comparison must never use.
      if (offset === 10 + (index % 3))
        push({ ...base('phq2'), indicator: 'mood', kind: 'phq2', score: index % 3 })
    })
  }
  return entries
}

/** The crew data used by the app: simulated in this prototype. */
export function simulatedCrewSource(now: Date): CrewDataSource {
  return { kind: 'simulated', selfId: SELF_ID, entries: createCrewEntries(now) }
}
